import {CityMap} from './city.js';import {Player} from './player.js';import {Vehicle,VEHICLE_TYPES} from './vehicles.js';import {TrafficAI} from './traffic.js';import {PedestrianCrowd} from './pedestrians.js';import {WantedSystem} from './wanted.js';import {PoliceForce} from './police.js';import {Effects} from './effects.js';
export const World=class World{
 constructor(rng){this.rng=rng;this.city=new CityMap(rng);this.time=0;this.objective=null;this.playerStart={x:720,y:880};this.player=new Player(this.playerStart.x,this.playerStart.y);this.vehicles=[];for(let i=0;i<26;i++){const p=this.city.randomRoadPoint(rng);p.x+=rng.range(-18,18);this.vehicles.push(new Vehicle(p.x,p.y,rng.pick(Object.keys(VEHICLE_TYPES)),null,rng.chance(.5)?0:Math.PI));}for(let i=0;i<4;i++)this.vehicles.push(new Vehicle(535,680+i*145,rng.pick(Object.keys(VEHICLE_TYPES)),null,0));this.driving=null;this.heat=0;this.money=500;this.health=100;this.bustMeter=0;this.busted=false;this.camera=null;this.traffic=new TrafficAI(this);this.pedestrians=new PedestrianCrowd(this);this.wanted=new WantedSystem(this);this.police=new PoliceForce(this);this.effects=new Effects(this);}
 nearestCar(x,y,maxDist){let best=null,d=maxDist;for(const v of this.vehicles){if(v.driver)continue;const n=Math.hypot(x-v.x,y-v.y);if(n<d){best=v;d=n;}}return best;}
 step(dt,input={down:()=>false,actions:0}){this.time+=dt;if(this.driving?._carjack){this.wanted.reportCrime('carjack');delete this.driving._carjack;}this.player.update(dt,input,this);this.traffic.update(dt);this.pedestrians.update(dt);this.wanted.update(dt);this.police.update(dt);if(this.driving&&Math.abs(this.driving.speed)>45)for(const p of this.pedestrians.people)if(!p._hit&&Math.hypot(p.x-this.driving.x,p.y-this.driving.y)<18){p._hit=2;p.cower=2;this.wanted.reportCrime('pedestrian');}for(const p of this.pedestrians.people)if(p._hit>0)p._hit-=dt;for(let i=0;i<this.vehicles.length;i++)for(let j=i+1;j<this.vehicles.length;j++){const a=this.vehicles[i],b=this.vehicles[j];if(Math.hypot(a.x-b.x,a.y-b.y)<22&&a.speed>50&&b.speed>50){a.damage=Math.min(1,a.damage+.04);b.damage=Math.min(1,b.damage+.04);a.speed*=.4;b.speed*=.4;this.effects.burst((a.x+b.x)/2,(a.y+b.y)/2);if(a===this.driving||b===this.driving){this.wanted.reportCrime('crash');if(a.type==='police'||b.type==='police')this.wanted.reportCrime('police');}for(const p of this.pedestrians.people)if(Math.hypot(p.x-a.x,p.y-a.y)<50)p.cower=2;}}
 this.effects.update(dt);}
};
