import {Vehicle} from './vehicles.js';
export class TrafficAI {
 constructor(world){this.world=world;this.cars=[];this.timers=new Map();}
 update(dt){const w=this.world,p=w.driving||w.player;for(const v of this.cars){if(!w.vehicles.includes(v))continue;if(v._crash>0){v._crash-=dt;v.speed=0;continue;}if(v._crash!==undefined)delete v._crash;for(const q of w.vehicles){if(q!==v&&q!==p&&Math.hypot(q.x-v.x,q.y-v.y)<25&&Math.abs(q.speed)>35){v._crash=3;v.speed=0;break;}}if(v._crash>0)continue;let target=v._target;if(!target||Math.hypot(target.x-v.x,target.y-v.y)<36){const r=w.rng.pick(w.city.roads);target=r.x1===r.x2?{x:r.x1,y:w.rng.range(0,w.city.height)}:{x:w.rng.range(500,w.city.width),y:r.y1};v._target=target;}const a=Math.atan2(target.x-v.x,-(target.y-v.y)),delta=Math.atan2(Math.sin(a-v.angle),Math.cos(a-v.angle));let throttle=.65,steer=Math.max(-1,Math.min(1,delta*2));for(const q of [...w.vehicles,...w.pedestrians.people]){if(q===v)continue;const dx=q.x-v.x,dy=q.y-v.y,forward=dx*Math.sin(v.angle)-dy*Math.cos(v.angle),side=dx*Math.cos(v.angle)+dy*Math.sin(v.angle);if(forward>0&&forward<100&&Math.abs(side)<34){throttle=-.5;if(q===p&&Math.abs(v.speed)>30&&w.rng.chance(.012))v._honk=1;break;}}if(Math.abs(delta)>1.4)throttle*=.5;v.update(dt,{throttle,steer},w);if(v._honk>0)v._honk-=dt;}
  const nearby=this.cars.filter(v=>Math.hypot(v.x-p.x,v.y-p.y)<1100);while(nearby.length<14){const r=w.rng.pick(w.city.roads),pos=r.x1===r.x2?{x:r.x1,y:Math.max(40,Math.min(3500,p.y+w.rng.range(-850,850)))}:{x:Math.max(550,Math.min(4700,p.x+w.rng.range(-850,850))),y:r.y1},d=Math.hypot(pos.x-p.x,pos.y-p.y);if(d<180||d>1050)continue;const v=new Vehicle(pos.x,pos.y,w.rng.pick(['sedan','taxi','pickup']),null,r.x1===r.x2?(p.y<pos.y?0:Math.PI):(p.x<pos.x?Math.PI/2:-Math.PI/2));v.driver='traffic';w.vehicles.push(v);this.cars.push(v);nearby.push(v);}for(let i=this.cars.length-1;i>=0;i--){const v=this.cars[i],d=Math.hypot(v.x-p.x,v.y-p.y);if(d>1450||d<120){w.vehicles.splice(w.vehicles.indexOf(v),1);this.cars.splice(i,1);}}
 }
